SELECT ,
FROM book_purchase p LEFT JOIN book_category c ON p.category_id = c.id LEFT JOIN integration_app a ON p.app_id = a.id LEFT JOIN integration_form f ON p.integration_form_id = f.id LEFT JOIN purchase_flow pf ON pf.purchase_id = p.id AND pf.is_deleted = 0
ORDER BY p.id DESC LIMIT #{offset}, #{limit}
